#!/usr/bin/env python3
"""Audit active product legacy references; retain exact historical evidence."""
from pathlib import Path
import subprocess,re,json
root=Path(__file__).resolve().parent.parent
pattern=re.compile(r'clarity[ _-]*(?:square|circle)|ClaritySquare|ClarityCircle|squareProject|square-thread|circle-thread|square_post|ccmc?1|--square-|\b(?:square|circle)\b|\bSquare[A-Z]\w*|\b[a-z]\w*Square\w*',re.I)
entries=[]
for name in sorted(set(subprocess.check_output(['git','ls-files','--cached','--others','--exclude-standard'],cwd=root,text=True).splitlines())):
 p=root/name
 if not p.is_file() or name.startswith('work/') or name in ['scripts/audit-spasht-references.py','docs/spasht/residual-reference-audit.json','docs/spasht/residual-reference-audit.md']:continue
 try:lines=p.read_text().splitlines()
 except (UnicodeError,ValueError):continue
 hits=[i for i,s in enumerate(lines,1) if pattern.search(s)]
 if not hits:continue
 if name.startswith('supabase/migrations/') and not name.endswith('_spasht_rebrand.sql'):reason='Immutable applied migration history; later migration renames current objects'
 elif name in ['09_reviews/decisions.md','docs/kramaniti-scaling/00-repository-audit.md','docs/kramaniti-scaling/04-decision-log.md','docs/clarity_square_first_20_journey_review.md'] or name.startswith('docs/clarity-square/'):reason='Dated decisions, reviews or exact recovery evidence; not active product identity'
 elif name.startswith('website/tests/'):reason='Fixtures and assertions exercise legacy reads, redirects and identity preservation'
 elif name=='website/next.config.ts':reason='Permanent old entry redirects and method-preserving API adapters'
 elif name=='website/src/lib/spasht/navigation.ts':reason='Legacy square/circle query aliases resolve to canonical community'
 elif name=='website/src/lib/spasht/compatibility.ts':reason='Browser-state, saved-payload, thread and immutable approval receipt read adapters'
 elif name=='website/src/app/spasht/Spasht.tsx':reason='Display normalization and restoration of saved legacy thread/view values'
 elif name.startswith('website/spasht-chatgpt-app/src/'):reason='Existing OAuth scope/token or widget URI read compatibility'
 elif name.endswith('_spasht_rebrand.sql') or name=='docs/spasht/rollback.sql':reason='Source schema names, data-preserving event compatibility and reversible migration'
 elif name.startswith('docs/'):reason='Historical migration links, explicit transition notes, or parent geometry and distinct product names'
 elif name.endswith(('.css','.svg','.html')) or name in ['website/src/app/agent-simulation/page.tsx','website/src/app/hq/KramanitiHq.tsx']:reason='Generic geometry, CSS gradients, icon names or distinct products; no legacy workspace identity'
 elif name.startswith(('02_founder_context/','03_brand_strategy/','08_brand_assets/')) or name.startswith('scripts/render_kramaniti_') or name.startswith('website/src/components/') or name.startswith('agent-os-simulation/') or name in ['kramaniti-hq.config.json','website/src/app/work/maitri/page.tsx','website/src/data/kramaniti-hq-repositories.generated.json','website/src/lib/clarity-engine/assistant.ts']:reason='Reviewed generic geometry, input vocabulary, or separate Binance Square/Maitri Circle identity'
 else:reason='UNACCOUNTED'
 entries.append({'file':name,'lines':hits,'count':len(hits),'purpose':reason})
(root/'docs/spasht/residual-reference-audit.json').write_text(json.dumps(entries,indent=2)+'\n')
md='# Spasht residual reference audit\n\n[Fact] Generated by `python3 scripts/audit-spasht-references.py`. Covers tracked text plus non-ignored additions; excludes private work output and generated audit files. Exact line inventories are in `residual-reference-audit.json`. Historical names are intentionally retained for identity, compatibility or recovery.\n\n| File | Matching lines | Purpose |\n| --- | ---: | --- |\n'
for e in entries:md+=f"| `{e['file']}` | {e['count']} | {e['purpose']} |\n"
md+='\n[Constraint] Persisted member prose, event metadata, custom thread IDs and receipt UUIDs are not bulk rewritten; these are private historical data. Generic geometry and icon names (CircleDot, aspect-square), the separate Clarity Engine/Clarity Brief, and Maitri Circle are not this product. External configuration is covered in the release plan and was not silently claimed renamed.\n'
(root/'docs/spasht/residual-reference-audit.md').write_text(md)
unknown=[e for e in entries if e['purpose']=='UNACCOUNTED'];print(json.dumps({'files':len(entries),'matching_lines':sum(e['count'] for e in entries),'unaccounted':unknown}));raise SystemExit(bool(unknown))
